WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='HOJA_DE_MATERIALES' AND v.numero=1)
INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT id,'LISTA DE MATERIALES Y/O CONSUMIBLES',1 FROM v ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
